package doccorpus

import (
	"context"
	"strings"
	"testing"
)

// generatedWorkspace commits generated outputs of four kinds into both repositories of
// workspaceRepos and returns the roots and their new revisions.
func generatedWorkspace(t *testing.T) (app, tests, appRevision, testsRevision string) {
	t.Helper()
	app, tests = workspaceRepos(t)
	appRevision = commitFiles(t, app, map[string]string{
		"docs/gen/reference.md": "# Reference\n",
		"docs/corpus.md":        "<!-- corvint-corpus profile -->\n# Corpus\n",
		"src/zz_out.go":         "// Code generated by tool. DO NOT EDIT.\n\npackage app\n",
	})
	testsRevision = commitFiles(t, tests, map[string]string{"pages/artifact.json": `{"schema":"corvint-corpus-input/1"}`})
	return app, tests, appRevision, testsRevision
}

// wantGeneratedRefusal checks that err names every expected input with its repository label,
// path, revision and matched check, in manifest order (DCP-V1-607, DCP-V1-608).
func wantGeneratedRefusal(t *testing.T, err error, want []string) {
	t.Helper()
	if err == nil {
		t.Fatal("generated source input admitted")
	}
	message := err.Error()
	if !strings.Contains(message, "generated output cannot be source input") {
		t.Fatalf("refusal %q does not name the generated-output rule", message)
	}
	at := 0
	for _, w := range want {
		i := strings.Index(message[at:], w)
		if i < 0 {
			t.Fatalf("refusal %q does not name %q after offset %d", message, w, at)
		}
		at += i + len(w)
	}
}

// TestDCPV1607BuildRefusalNamesEveryGeneratedInput: build lists every generated source input
// with its repository alias (or primary), path, revision and the matched check, not only the first.
func TestDCPV1607BuildRefusalNamesEveryGeneratedInput(t *testing.T) {
	t.Parallel()
	app, tests, appRevision, testsRevision := generatedWorkspace(t)
	m, err := InventoryWorkspace(context.Background(), app, appRevision, []string{"docs", "src"}, ManifestSchema, "2026-10-28T00:00:00Z", []WorkspaceRepository{{Alias: "e2e", Root: tests, Scopes: []string{"pages"}}})
	want := []string{
		"(4 inputs;",
		"repository=primary path=docs/corpus.md revision=" + appRevision + " check=corpus-marker",
		"repository=primary path=docs/gen/reference.md revision=" + appRevision + " check=generated-path",
		"repository=primary path=src/zz_out.go revision=" + appRevision + " check=code-generated-comment",
		"repository=e2e path=pages/artifact.json revision=" + testsRevision + " check=corpus-schema",
	}
	wantGeneratedRefusal(t, err, want)
	if len(m.Inputs) == 0 || len(m.AdditionalRepositories) != 1 {
		t.Fatalf("refused inventory returned no pinned manifest: %+v", m)
	}
	_, err = Build(context.Background(), app, m)
	wantGeneratedRefusal(t, err, want)
}

// TestDCPV1607GeneratedHeaderCheckIsNamed: the native Code-generated header rule is named
// generated-header when no earlier check matches.
func TestDCPV1607GeneratedHeaderCheckIsNamed(t *testing.T) {
	t.Parallel()
	for _, test := range []struct{ path, body, check string }{
		{"docs/a.md", "<!-- Code generated fixture DO NOT EDIT. -->\n# A\n", "generated-header"},
		{"docs/api/openapi.json", "{}\n", "generated-path"},
		{"docs/b.md", "# Plain\n", ""},
	} {
		if got := generatedCheck(test.path, []byte(test.body)); got != test.check {
			t.Fatalf("generatedCheck(%s) = %q, want %q", test.path, got, test.check)
		}
	}
}

// TestDCPV1608ManifestRefusesGeneratedInputsWhenPinning: a single-root manifest names every
// generated input when pinning; a scope without one inventories unchanged, and the library
// InventoryScopes that flowdocs uses for provider records still pins generated output.
func TestDCPV1608ManifestRefusesGeneratedInputsWhenPinning(t *testing.T) {
	t.Parallel()
	app, _, appRevision, _ := generatedWorkspace(t)
	_, err := ManifestInventory(context.Background(), app, appRevision, []string{"docs", "src"}, ManifestSchema, "2026-10-28T00:00:00Z")
	wantGeneratedRefusal(t, err, []string{
		"(3 inputs;",
		"repository=primary path=docs/corpus.md revision=" + appRevision + " check=corpus-marker",
		"repository=primary path=docs/gen/reference.md",
		"repository=primary path=src/zz_out.go",
	})
	if _, err := ManifestInventory(context.Background(), app, appRevision, []string{"docs/login.md"}, ManifestSchema, "2026-10-28T00:00:00Z"); err != nil {
		t.Fatalf("scope without generated output refused: %v", err)
	}
	if m, err := InventoryScopes(context.Background(), app, appRevision, []string{"docs", "src"}, ManifestSchema, "2026-10-28T00:00:00Z"); err != nil || len(m.Inputs) == 0 {
		t.Fatalf("library inventory refused generated output: %v", err)
	}
}
